class Solution:
    def countValidSubarrays(self, nums, k):
        n = len(nums)
        ans = 0
        for i in range(1, n - 1):
            if nums[i] > nums[i - 1] and nums[i] > nums[i + 1]:
                lo = max(0, i - k)
                hi = min(n - 1, i + k)
                ans += (i - lo + 1) * (hi - i + 1)
        return ans

